for n,slug,title,seo,meta,focus,keys,intro,secs,faqs,sources in A:
 L=['---',f'article_number: {n}','status: awaiting-featured-image',f'slug: {slug}','---','','## اطلاعات اولیه','',f'- **عنوان اصلی:** {title}',f'- **عنوان SEO:** {seo}',f'- **توضیحات متا:** {meta}',f'- **اسلاگ:** `{slug}`',f'- **کلیدواژه اصلی:** {focus}',f'- **کلیدواژه‌های فرعی:** {keys}','- **دسته:** رایانش و ارتباطات کوانتومی','',f'# {title}','',intro,'']
 for h,b in secs:L += [f'## {h}','',b,'']
 L += ['## جمع‌بندی','',f'{focus} را باید همراه با هزینه آماده‌سازی، تعداد گیت، نمونه‌برداری، نویز و بهترین روش کلاسیک سنجید. یک بهبود نظری فقط زمانی کاربردی است که کل زنجیره محاسبه را بهتر کند.','','## پرسش‌های متداول','']
 for q,a in faqs:L += [f'<p><strong>{q}</strong></p>',f'<p>{a}</p>','']
 L += ['## منابع','']+[f'{i}. {x}' for i,x in enumerate(sources,1)]
 Path(f'articles/{n:02d}-{slug}.md').write_text('\n'.join(L)+'\n')
 Path(f'articles/{n:02d}-{slug}.review.md').write_text(f'# پرونده کنترل مقاله {n}: {focus}\n\n- تصویر: در انتظار دریافت\n- یک H1: بله\n- مقدمه بدون تیتر: بله\n- FAQ با HTML ساده و سؤال‌های بولد: بله\n- منابع آخرین بخش: بله\n- نقل‌قول مستقیم: ندارد\n- وضعیت: REVIEW تا دریافت تصویر\n')
